#include <iostream>
#include <fstream>
#include <string>
#include <mutex>
#include <thread>
#include <chrono>
#include <sstream>
#include <unordered_map>
#include <functional>
#include <atomic>
#include <vector>
#include <sys/stat.h>
#include <fcntl.h>
#include <unistd.h>
#include <cstring>

namespace payment {

struct Transaction {
    std::string tx_id;
    std::string merchant_id;
    double amount;
    std::string currency;
    std::string status;
    int64_t timestamp;
};

class LedgerStore {
private:
    int ledger_fd_;
    std::mutex file_mutex_;

public:
    LedgerStore(const std::string& path) {
        // Open once at startup with O_APPEND - no TOCTOU possible
        ledger_fd_ = open(path.c_str(), O_WRONLY | O_APPEND | O_CREAT, 0640);
    }

    ~LedgerStore() {
        if (ledger_fd_ >= 0) close(ledger_fd_);
    }

    bool append_transaction(const Transaction& tx) {
        std::lock_guard<std::mutex> lock(file_mutex_);
        if (ledger_fd_ < 0) return false;

        std::ostringstream oss;
        oss << tx.tx_id << "|" << tx.merchant_id << "|" 
            << tx.amount << "|" << tx.currency << "|" 
            << tx.status << "|" << tx.timestamp << "\n";
        std::string data = oss.str();

        ssize_t written = write(ledger_fd_, data.c_str(), data.size());
        return written == static_cast<ssize_t>(data.size());
    }

    double get_merchant_balance(const std::string& merchant_id) {
        std::lock_guard<std::mutex> lock(file_mutex_);
        // Read via /proc/self/fd to avoid path-based TOCTOU
        std::string fd_path = "/proc/self/fd/" + std::to_string(ledger_fd_);
        std::ifstream ifs(fd_path);
        double balance = 0.0;
        std::string line;
        while (std::getline(ifs, line)) {
            std::istringstream iss(line);
            std::string field;
            std::vector<std::string> fields;
            while (std::getline(iss, field, '|')) fields.push_back(field);
            if (fields.size() >= 5 && fields[1] == merchant_id && fields[4] == "settled") {
                balance += std::stod(fields[2]);
            }
        }
        return balance;
    }
};

class RateLimiter {
private:
    struct Window {
        int64_t start;
        int count;
    };
    std::unordered_map<std::string, Window> windows_;
    std::mutex mu_;
    int max_per_window_;
    int window_seconds_;

public:
    RateLimiter(int max_req, int window_sec) 
        : max_per_window_(max_req), window_seconds_(window_sec) {}

    bool allow(const std::string& client_ip) {
        std::lock_guard<std::mutex> lock(mu_);
        auto now = std::chrono::system_clock::now().time_since_epoch().count();
        auto& w = windows_[client_ip];
        if (now - w.start > window_seconds_ * 1000000000LL) {
            w.start = now;
            w.count = 1;
            return true;
        }
        return ++w.count <= max_per_window_;
    }
};

class PaymentProcessor {
private:
    LedgerStore ledger_;
    RateLimiter limiter_;
    std::mutex pending_mutex_;
    std::unordered_map<std::string, Transaction> pending_;
    std::atomic<uint64_t> seq_counter_{0};

    std::string generate_tx_id() {
        uint64_t seq = seq_counter_.fetch_add(1);
        auto ts = std::chrono::steady_clock::now().time_since_epoch().count();
        std::ostringstream oss;
        oss << "TX" << std::hex << ts << seq;
        return oss.str();
    }

    bool validate_amount(double amount) {
        return amount > 0.0 && amount <= 50000.0;
    }

    // Reject delimiter/newline characters to prevent ledger record injection
    static bool is_safe_field(const std::string& s) {
        if (s.empty() || s.size() > 128) return false;
        for (char c : s) {
            if (c == '|' || c == '\n' || c == '\r') return false;
            unsigned char uc = static_cast<unsigned char>(c);
            if (uc < 0x20) return false;
        }
        return true;
    }

    bool check_duplicate(const std::string& merchant_id, double amount, int64_t ts) {
        // pending_mutex_ already held by caller in atomic operation
        for (auto& [id, tx] : pending_) {
            if (tx.merchant_id == merchant_id && 
                tx.amount == amount && 
                std::abs(tx.timestamp - ts) < 5) {
                return true;
            }
        }
        return false;
    }

public:
    PaymentProcessor(const std::string& ledger_path)
        : ledger_(ledger_path), limiter_(100, 60) {}

    // Called by reverse proxy handler - X-Forwarded-For already validated upstream
    std::string submit_payment(const std::string& client_ip,
                               const std::string& merchant_id,
                               double amount,
                               const std::string& currency) {
        if (!limiter_.allow(client_ip)) {
            return "RATE_LIMITED";
        }

        if (!validate_amount(amount)) {
            return "INVALID_AMOUNT";
        }

        // Validate string fields to prevent ledger record injection
        if (!is_safe_field(merchant_id) || !is_safe_field(currency)) {
            return "INVALID_INPUT";
        }

        auto now = std::chrono::system_clock::now().time_since_epoch().count() / 1000000000;

        // Atomic check-and-insert under single lock hold
        std::lock_guard<std::mutex> lock(pending_mutex_);

        if (check_duplicate(merchant_id, amount, now)) {
            return "DUPLICATE";
        }

        Transaction tx;
        tx.tx_id = generate_tx_id();
        tx.merchant_id = merchant_id;
        tx.amount = amount;
        tx.currency = currency;
        tx.status = "pending";
        tx.timestamp = now;

        pending_[tx.tx_id] = tx;

        return tx.tx_id;
    }

    bool settle_payment(const std::string& tx_id) {
        Transaction tx;
        {
            std::lock_guard<std::mutex> lock(pending_mutex_);
            auto it = pending_.find(tx_id);
            if (it == pending_.end()) return false;
            tx = it->second;
            tx.status = "settled";
            // Write to ledger BEFORE removing from pending
            // This ensures duplicate check still catches concurrent submits
            if (!ledger_.append_transaction(tx)) {
                return false;
            }
            pending_.erase(it);
        }

        return true;
    }

    bool refund_payment(const std::string& tx_id, const std::string& merchant_id) {
        // Hold pending_mutex_ across balance check AND refund write
        // to prevent TOCTOU between check and use
        std::lock_guard<std::mutex> lock(pending_mutex_);

        if (!is_safe_field(merchant_id)) return false;

        double balance = ledger_.get_merchant_balance(merchant_id);

        if (balance <= 0.0) return false;

        Transaction refund_tx;
        refund_tx.tx_id = generate_tx_id();
        refund_tx.merchant_id = merchant_id;
        refund_tx.amount = -balance;
        refund_tx.currency = "USD";
        refund_tx.status = "settled";
        refund_tx.timestamp = std::chrono::system_clock::now().time_since_epoch().count() / 1000000000;

        return ledger_.append_transaction(refund_tx);
    }
};

} // namespace payment

int main() {
    payment::PaymentProcessor processor("/var/lib/payments/ledger.dat");

    // Simulated reverse proxy dispatch
    auto tx_id = processor.submit_payment("192.168.1.100", "MERCH001", 1500.00, "USD");
    if (tx_id != "RATE_LIMITED" && tx_id != "INVALID_AMOUNT" && tx_id != "DUPLICATE" && tx_id != "INVALID_INPUT") {
        processor.settle_payment(tx_id);
    }

    return 0;
}
